const Point=struct{infinity:bool,x:i64,y:i64};
fn md(v:i64,m:i64)i64{const r=@rem(v,m);return if(r<0) r+m else r;}
fn inverse(v0:i64,m:i64)i64{var old_r=m;var r=md(v0,m);var old_t:i64=0;var t:i64=1;while(r!=0){const q=@divTrunc(old_r,r);const nr=old_r-q*r;const nt=old_t-q*t;old_r=r;r=nr;old_t=t;t=nt;}return if(old_r==1) md(old_t,m) else 0;}
fn inf()Point{return .{.infinity=true,.x=0,.y=0};}
fn add(u:Point,v:Point)Point{if(u.infinity)return v;if(v.infinity)return u;if(u.x==v.x and md(u.y+v.y,17)==0)return inf();const same=u.x==v.x and u.y==v.y;const num=if(same) md(3*u.x*u.x+2,17) else md(v.y-u.y,17);const den=if(same) md(2*u.y,17) else md(v.x-u.x,17);const slope=md(num*inverse(den,17),17);const x=md(slope*slope-u.x-v.x,17);return .{.infinity=false,.x=x,.y=md(slope*(u.x-x)-u.y,17)};}
fn mul(q0:Point,k0:i64)Point{var q=q0;var k=k0;var result=inf();while(k>0){if((k&1)!=0)result=add(result,q);k>>=1;if(k>0)q=add(q,q);}return result;}
fn onCurve(q:Point)bool{return md(q.y*q.y-q.x*q.x*q.x-2*q.x-2,17)==0;}
export fn ecdsa_signature_verification(v:?[*]const i64,n:usize,o:?[*]u8,cap:usize)i64{if(n!=11)return -1;const input=v orelse return -1;const p=input[0];const a=input[1];const b=input[2];const gx=input[3];const gy=input[4];const order=input[5];const qx=input[6];const qy=input[7];const z=input[8];const r=input[9];const s=input[10];if(p!=17 or a!=2 or b!=2 or gx!=5 or gy!=1 or order!=19)return -1;if(md(4*a*a*a+27*b*b,p)==0 or qx<0 or qx>=p or qy<0 or qy>=p or z<0 or z>31 or r<1 or r>=order or s<1 or s>=order)return -1;const g=Point{.infinity=false,.x=gx,.y=gy};const q=Point{.infinity=false,.x=qx,.y=qy};if(!onCurve(g) or !onCurve(q) or !mul(g,order).infinity or !mul(q,order).infinity)return -1;if(cap<1)return -2;const output=o orelse return -2;const w=inverse(s,order);if(w==0)return -1;const u1=z*w%order;const u2=r*w%order;const check=add(mul(g,u1),mul(q,u2));output[0]=@intFromBool(!check.infinity and check.x%order==r);return 1;}
